package com.profa.document;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity @Table(name="teacher_documents")public class TeacherDocument{@Id@GeneratedValue(strategy=GenerationType.UUID)UUID id;UUID teacherId;String type;String fileUrl;String status="PENDING";String rejectionReason;Instant createdAt=Instant.now();public UUID getId(){return id;}public UUID getTeacherId(){return teacherId;}public void setTeacherId(UUID v){teacherId=v;}public String getType(){return type;}public void setType(String v){type=v;}public String getFileUrl(){return fileUrl;}public void setFileUrl(String v){fileUrl=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getRejectionReason(){return rejectionReason;}public void setRejectionReason(String v){rejectionReason=v;}}